mapper.select:
select * from ( select row_number() over (order by user_num) as rn , user_num, user_name, user_id , u.department_id, department_name as department_name , u.grade_id, grade_name as grade_name from user u left join department d on u.department_id=d.department_id left join grade g on u.grade_id=g.grade_id
where user_name like concat('%',#{searchWord},'%') or user_id like concat('%',#{searchWord},'%')
) as sub where rn between #{startRow} and #{endRow}

mapper.update:
update user
set user_name = #{userName}, user_pw = #{userPw}
, department_id = #{departmentId}, grade_id = #{gradeId}
, manager = #{manager}
where user_num = #{userNum}
